  it("uses selected excerpts for text extraction rather than whole text when excerpts are present", async () => {
    const rawText =
      "Cookie settings and site banner.\n\n" +
      "The new BMW 120 steering offers remarkable precision and agility on winding roads.\n\n" +
      "Terms of service and footer navigation.";

    const item = CollectedItem.parse({
      provider: "firecrawl",
      sourceId: "source_review_excerpt",
      sourceUrl: "https://auto-review.example.org/bmw-steering",
      sourceTitle: "Steering Review",
      publisher: "Auto Mag",
      recordId: "doc_excerpt",
      recordType: "passage",
      text: rawText,
      locator: "article section",
      metadata: {},
    });

    const { source, record } = normalizeItem(item, "editorial_reviews", "run_test", at);
    const targetExcerpt = "The new BMW 120 steering offers remarkable precision and agility on winding roads.";
    const start = rawText.indexOf(targetExcerpt);
    const end = start + targetExcerpt.length;

    const assessment: SourceAssessment = {
      version: 1,
      agentId: "editorial_reviews",
      contentHash: record.contentHash,
      scope: ResearchScope.parse({ model: "1 Series", markets: ["EU"] }),
      runId: "run_test",
      verdict: "relevant",
      reasons: ["Substantive steering feedback."],
      uncertainties: [],
      excerpts: [{ start, end }],
      tableRows: [],
      model: "test-model",
    };
    record.fields = {
      ...record.fields,
      [ASSESSMENT_FIELD]: [assessment],
    };

    const dataset = ResearchDataset.parse({
      schemaVersion: 1,
      runId: "run_test",
      retrievedAt: at,
      sources: [source],
      records: [record],
      results: [],
      synthetic: true,
    });

    // 1. Offline summarizer uses the excerpt rather than boilerplate
    const offlineRows = await summarizeResearchDataset(dataset, {
      scope,
      signal: new AbortController().signal,
    });

    expect(offlineRows).toHaveLength(1);
    expect(offlineRows[0]!.text).not.toContain("Cookie settings");
    expect(offlineRows[0]!.text).not.toContain("Terms of service");
    expect(offlineRows[0]!.text).toContain("remarkable precision and agility");
    expect(offlineRows[0]!.locator).toContain(`chars ${start + 1}–${end}`);
    expect(offlineRows[0]!.sourceAssessments).toEqual([
      { agentId: "editorial_reviews", verdict: "relevant", model: "test-model" },
    ]);

    // Direct offlineSummarizeRecord also respects assessedSelection
    const directOffline = offlineSummarizeRecord(record, source, scope);
    expect(directOffline.summary).not.toContain("Cookie settings");
    expect(directOffline.summary).toContain("remarkable precision and agility");

    // 2. LLM client receives extracted excerpts in content prompt
    let promptContent = "";
    const mockLlm: LlmClient = {
      generateObject: vi.fn(async (req) => {
        const parsedPrompt = JSON.parse(req.prompt);
        promptContent = parsedPrompt.content;
        return {
          model: "gemini-3.8-flash",
          object: SourceSummariesResult.parse({
            items: [
              {
                brand: "[BMW]",
                salesDescription: "[BMW 1 Series]",
                country: "DE",
                derivate: "F70",
                engineType: "ICE",
                feedbackType: "Likes",
                summary: "Steering dynamics are remarkably agile and precise.",
                vfcLevel2Name: "Handling / Riding",
                vfcLevel3Name: "Like: performance",
              },
            ],
          }),
        };
      }) as unknown as LlmClient["generateObject"],
      generateText: vi.fn(),
    };

    const llmRows = await summarizeResearchDataset(dataset, {
      llm: mockLlm,
      scope,
      signal: new AbortController().signal,
    });

    expect(promptContent).toBe(targetExcerpt);
    expect(promptContent).not.toContain("Cookie settings");
    expect(llmRows).toHaveLength(1);
    expect(llmRows[0]!.locator).toContain(`chars ${start + 1}–${end}`);
  });
